// ==== LLM CLASSIFY (STUB) — replace with a real LLM call ====
// Send the classification prompt below plus the message text/caption
// (and for audio, a transcript; for photos/documents, the file or OCR text)
// to your LLM. It must return STRICT JSON:
// { "type": "receipt|document|photo|journal|note|misc",
//   "title": string, "slug": string (kebab-case),
//   "date": "YYYY-MM-DD", "tags": string[], "area": string,
//   "payee": string?, "amount": number?, "currency": string?,
//   "summary": string }
const PROMPT = `You are Hermes' filing clerk. Classify the incoming Telegram item.\nReturn ONLY valid JSON with keys: type (one of receipt, document, photo, journal, note, misc), title, slug (kebab-case, <=6 words), date (YYYY-MM-DD, best guess, default today), tags (array of lowercase strings), area (life area e.g. finance, seafaring, home, health), payee (only for receipts), amount (number, only for receipts), currency (ISO 4217, only for receipts), summary (1-2 sentences).\nNo markdown, no commentary.`;

const msg = $('From Hermes').first().json.message;
const text = msg.text || msg.caption || '';
const today = new Date().toISOString().slice(0, 10);

// STUB result so the skeleton runs end-to-end:
return [{
  json: {
    prompt: PROMPT,
    classification: {
      type: msg.photo ? 'photo' : (msg.document ? 'document' : (msg.voice || msg.audio ? 'note' : 'note')),
      title: (text.replace(/^\/note\s*/, '') || 'Untitled capture').slice(0, 80),
      slug: (text.replace(/^\/note\s*/, '') || 'untitled-capture').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').split('-').slice(0, 6).join('-') || 'untitled-capture',
      date: today,
      tags: ['inbox'],
      area: 'misc',
      summary: text ? text.slice(0, 200) : 'Captured from Telegram.'
    }
  },
  binary: $binary
}];

// Map classification.type -> Filing Cabinet Drive folder ID
const FOLDERS = {
  receipt: '1bGLLsV-mqHTdyRoDTXgSutiC2bJaM_0i', // Receipts/2026
  document: '1v5kYPvNqWi9ln1C0dghK366bZ_7p4r0z', // Documents
  photo: '19YxSqKCLbUGzjirpTnkqbhOduitbLqCu', // Photos/2026
  misc: '1AhdmXeuRINPeu7KWhEfvGt7C6wnaOLCl' // Misc
};
const VAULT = {
  inbox: '1tYs7O6OrX9WNqXOaxPPAGlue5NyKVTiw', // 00 Inbox
  journal: '1Cw_pU3a-bNb4lMj4zbev8BFk6tjcayrx' // journal notes
};
const c = $json.classification;
const hasBinary = Object.keys($binary || {}).length > 0;
return [{
  json: {
    ...$json,
    targetFolderId: FOLDERS[c.type] || FOLDERS.misc,
    noteFolderId: c.type === 'journal' ? VAULT.journal : VAULT.inbox,
    hasBinary,
    driveFileName: `${c.date} ${c.title}`.slice(0, 100)
  },
  binary: $binary
}];

// Build the markdown note with YAML frontmatter
const prev = $('Pick Drive Folder').first().json;
const c = prev.classification;
const uploaded = $json.id ? $json : null; // Drive file (when a binary was uploaded)
const driveLink = uploaded ? (uploaded.webViewLink || `https://drive.google.com/file/d/${uploaded.id}/view`) : '';
const fm = [
  '---',
  `date: ${c.date}`,
  `type: ${c.type}`,
  `tags: [${(c.tags || []).join(', ')}]`,
  'source: telegram',
  `drive_link: ${driveLink}`
];
if (c.amount != null) fm.push(`amount: ${c.amount}`);
if (c.payee) fm.push(`payee: ${c.payee}`);
if (c.currency) fm.push(`currency: ${c.currency}`);
fm.push('---');
const body = [
  '',
  `# ${c.title}`,
  '',
  '## Summary',
  c.summary || '',
  '',
  '## Details',
  `- Area: ${c.area || 'misc'}`,
  `- Captured: ${new Date().toISOString()}`,
  '',
  '## Links',
  driveLink ? `- [Original in Drive](${driveLink})` : '- (text-only capture)'
].join('\n');
return [{
  json: {
    noteTitle: `${c.date} ${c.slug}.md`,
    noteContent: fm.join('\n') + body,
    noteFolderId: prev.noteFolderId,
    driveLink,
    cardText: `📥 Filed: *${c.title}*\nType: ${c.type} | Tags: ${(c.tags || []).join(', ')}${driveLink ? `\n${driveLink}` : ''}`
  }
}];
